package runner

import (
	"archive/tar"
	"compress/gzip"
	"context"
	"crypto/sha512"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"
)

// AgentRelease is one platform build of an agent runnerd may install. The
// catalog is generated by cmd/agentcatalog after it verifies the npm
// registry's signature; installs trust only these compiled-in hashes.
type AgentRelease struct {
	Agent        string
	Version      string
	GOOS         string
	GOARCH       string
	Package      string
	Triple       string
	SHA512       string
	UnpackedSize int64
}

// CodexPlatform maps a Go target to @openai/codex's npm package suffix and
// the Rust triple of its vendor directory, as the official launcher does.
type CodexPlatform struct{ GOOS, GOARCH, NPM, Triple string }

// CodexPlatforms lists the targets @openai/codex publishes native builds for.
func CodexPlatforms() []CodexPlatform { return append([]CodexPlatform(nil), codexPlatforms...) }

var codexPlatforms = []CodexPlatform{
	{"linux", "amd64", "linux-x64", "x86_64-unknown-linux-musl"},
	{"linux", "arm64", "linux-arm64", "aarch64-unknown-linux-musl"},
	{"darwin", "amd64", "darwin-x64", "x86_64-apple-darwin"},
	{"darwin", "arm64", "darwin-arm64", "aarch64-apple-darwin"},
	{"windows", "amd64", "win32-x64", "x86_64-pc-windows-msvc"},
	{"windows", "arm64", "win32-arm64", "aarch64-pc-windows-msvc"},
}

const (
	npmRegistry      = "https://registry.npmjs.org"
	maxAgentDownload = 1 << 30
	maxAgentFiles    = 1000
	agentReceipt     = ".installed.json"
)

var ErrAgentUnsupported = errors.New("no managed agent release for this platform")

// ManagedAgentsDir keeps installed agents beside the runner state, inside
// the user's private configuration directory.
func ManagedAgentsDir(statePath string) string {
	return filepath.Join(filepath.Dir(statePath), "agents")
}

// AgentInstaller installs pinned agent releases into Root without
// administrator rights and without touching PATH or the agent's own config.
type AgentInstaller struct {
	Root     string
	Client   *http.Client
	Progress func(done, total int64)

	registry string
	catalog  []AgentRelease
	goos     string
	goarch   string
}

func (i *AgentInstaller) defaults() {
	if i.registry == "" {
		i.registry = npmRegistry
	}
	if i.catalog == nil {
		i.catalog = agentCatalog
	}
	if i.goos == "" {
		i.goos, i.goarch = runtime.GOOS, runtime.GOARCH
	}
}

// Release reports the pinned build of agent for this machine.
func (i *AgentInstaller) Release(agent string) (AgentRelease, bool) {
	i.defaults()
	for _, r := range i.catalog {
		if r.Agent == agent && r.GOOS == i.goos && r.GOARCH == i.goarch {
			return r, true
		}
	}
	return AgentRelease{}, false
}

func (i *AgentInstaller) dir(r AgentRelease) string {
	return filepath.Join(i.Root, r.Agent, r.Version+"-"+r.Triple)
}

func (i *AgentInstaller) executable(r AgentRelease) string {
	name := r.Agent
	if r.GOOS == "windows" {
		name += ".exe"
	}
	return filepath.Join(i.dir(r), "bin", name)
}

type installReceipt struct {
	Agent       string    `json:"agent"`
	Version     string    `json:"version"`
	Triple      string    `json:"triple"`
	SHA512      string    `json:"sha512"`
	InstalledAt time.Time `json:"installed_at"`
}

// Installed returns the managed executable when the pinned release finished
// installing; a directory without its receipt is an interrupted install.
func (i *AgentInstaller) Installed(agent string) (string, bool) {
	r, ok := i.Release(agent)
	if !ok {
		return "", false
	}
	raw, err := os.ReadFile(filepath.Join(i.dir(r), agentReceipt))
	var receipt installReceipt
	if err != nil || json.Unmarshal(raw, &receipt) != nil || receipt.SHA512 != r.SHA512 || receipt.Version != r.Version {
		return "", false
	}
	info, err := os.Lstat(i.executable(r))
	if err != nil || !info.Mode().IsRegular() {
		return "", false
	}
	return i.executable(r), true
}

// Install downloads the pinned release from the npm registry, checks it
// against the compiled-in SHA-512 before unpacking anything, and unpacks
// only the native vendor tree into a fresh directory.
func (i *AgentInstaller) Install(ctx context.Context, agent string) (string, error) {
	r, ok := i.Release(agent)
	if !ok {
		return "", ErrAgentUnsupported
	}
	if path, ok := i.Installed(agent); ok {
		return path, nil
	}
	if err := os.MkdirAll(i.Root, 0700); err != nil {
		return "", err
	}
	archive, err := os.CreateTemp(i.Root, ".download-*")
	if err != nil {
		return "", err
	}
	defer os.Remove(archive.Name())
	defer archive.Close()
	if err := i.download(ctx, r, archive); err != nil {
		return "", err
	}
	staging, err := os.MkdirTemp(i.Root, ".staging-*")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(staging)
	if err := extractVendor(archive, staging, "package/vendor/"+r.Triple+"/", r.UnpackedSize); err != nil {
		return "", err
	}
	name := filepath.Base(i.executable(r))
	if info, err := os.Lstat(filepath.Join(staging, "bin", name)); err != nil || !info.Mode().IsRegular() {
		return "", errors.New("agent package has no executable for this platform")
	}
	receipt, _ := json.Marshal(installReceipt{Agent: r.Agent, Version: r.Version, Triple: r.Triple, SHA512: r.SHA512, InstalledAt: time.Now().UTC()})
	if err := os.WriteFile(filepath.Join(staging, agentReceipt), receipt, 0600); err != nil {
		return "", err
	}
	final := i.dir(r)
	if err := os.MkdirAll(filepath.Dir(final), 0700); err != nil {
		return "", err
	}
	// A directory without a receipt is a crashed earlier attempt.
	_ = os.RemoveAll(final)
	if err := os.Rename(staging, final); err != nil {
		return "", err
	}
	entries, _ := os.ReadDir(filepath.Dir(final))
	for _, entry := range entries {
		if entry.Name() != filepath.Base(final) {
			_ = os.RemoveAll(filepath.Join(filepath.Dir(final), entry.Name()))
		}
	}
	return i.executable(r), nil
}

func (i *AgentInstaller) download(ctx context.Context, r AgentRelease, file *os.File) error {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Minute)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, i.registry+"/@openai/codex/-/codex-"+r.Package+".tgz", nil)
	if err != nil {
		return err
	}
	response, err := httpClient(i.Client).Do(request)
	if err != nil {
		return fmt.Errorf("downloading %s %s failed: %w", r.Agent, r.Version, err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return fmt.Errorf("downloading %s %s failed (HTTP %d)", r.Agent, r.Version, response.StatusCode)
	}
	if response.ContentLength > maxAgentDownload {
		return errors.New("agent download is larger than allowed")
	}
	digest := sha512.New()
	counter := &progressWriter{total: response.ContentLength, report: i.Progress}
	written, err := io.Copy(io.MultiWriter(file, digest, counter), io.LimitReader(response.Body, maxAgentDownload+1))
	if err != nil {
		return fmt.Errorf("downloading %s %s failed: %w", r.Agent, r.Version, err)
	}
	if written > maxAgentDownload || response.ContentLength >= 0 && written != response.ContentLength {
		return errors.New("agent download was truncated or oversized")
	}
	if subtle.ConstantTimeCompare([]byte(hex.EncodeToString(digest.Sum(nil))), []byte(r.SHA512)) != 1 {
		return fmt.Errorf("%s %s download does not match the pinned SHA-512; nothing was installed", r.Agent, r.Version)
	}
	return file.Sync()
}

type progressWriter struct {
	done, total int64
	report      func(done, total int64)
}

func (p *progressWriter) Write(b []byte) (int, error) {
	p.done += int64(len(b))
	if p.report != nil {
		p.report(p.done, p.total)
	}
	return len(b), nil
}

// extractVendor unpacks regular files and directories under prefix. Links,
// devices, absolute or escaping paths, and archives beyond the expected size
// or file count abort the install.
func extractVendor(archive *os.File, dest, prefix string, unpacked int64) error {
	if _, err := archive.Seek(0, io.SeekStart); err != nil {
		return err
	}
	compressed, err := gzip.NewReader(archive)
	if err != nil {
		return errors.New("agent package is not a gzip archive")
	}
	reader := tar.NewReader(compressed)
	limit := unpacked + 1<<20
	var total int64
	files := 0
	for {
		header, err := reader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return errors.New("agent package is corrupt")
		}
		rel, ok := strings.CutPrefix(header.Name, prefix)
		if !ok || rel == "" {
			continue
		}
		local := filepath.FromSlash(strings.TrimSuffix(rel, "/"))
		if !filepath.IsLocal(local) || strings.ContainsAny(rel, "\\:") {
			return fmt.Errorf("agent package contains an unsafe path %q", header.Name)
		}
		target := filepath.Join(dest, local)
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0755); err != nil {
				return err
			}
		case tar.TypeReg:
			files++
			total += header.Size
			if files > maxAgentFiles || header.Size < 0 || total > limit {
				return errors.New("agent package is larger than its release")
			}
			if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
				return err
			}
			mode := os.FileMode(0644)
			if header.Mode&0111 != 0 {
				mode = 0755
			}
			out, err := os.OpenFile(target, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
			if err != nil {
				return err
			}
			_, err = io.CopyN(out, reader, header.Size)
			if closeErr := out.Close(); err == nil {
				err = closeErr
			}
			if err != nil {
				return errors.New("agent package is truncated")
			}
		default:
			return fmt.Errorf("agent package contains an unsupported entry %q", header.Name)
		}
	}
	if files == 0 {
		return errors.New("agent package has no files for this platform")
	}
	return nil
}
